from collections import OrderedDict
from typing import Any, Optional, List

class LRUCache:
    def __init__(self, capacity: int):
        if capacity < 1:
            raise ValueError("Capacity must be at least 1")
        self.capacity = capacity
        self.cache = OrderedDict()

    def get(self, key: Any, default: Any = None) -> Any:
        if key not in self.cache:
            return default
        self.cache.move_to_end(key)
        return self.cache[key]

    def put(self, key: Any, value: Any) -> Optional[Any]:
        if key in self.cache:
            self.cache[key] = value
            self.cache.move_to_end(key)
            return None

        if len(self.cache) >= self.capacity:
            # Evict the first item (Least Recently Used)
            lru_key, _ = self.cache.popitem(last=False)
            return lru_key

        self.cache[key] = value
        self.cache.move_to_end(key)
        return None

    def __len__(self) -> int:
        return len(self.cache)

    def __contains__(self, key: Any) -> bool:
        return key in self.cache

    def keys(self) -> List[Any]:
        # OrderedDict keys() returns keys in insertion order, which is LRU to MRU
        return list(self.cache.keys())

    def resize(self, capacity: int) -> List[Any]:
        if capacity < 1:
            raise ValueError("Capacity must be at least 1")

        evicted_keys = []

        # Determine how many items to evict
        while len(self.cache) > capacity:
            # Evict the least recently used item
            lru_key, _ = self.cache.popitem(last=False)
            evicted_keys.append(lru_key)

        self.capacity = capacity
        return evicted_keys
