                new_value_part = line.strip()
                current_value = config._sections[current_section][last_key]
                config._sections[current_section][last_key] = f"{current_value}\n{new_value_part}"
                last_key_info['continuation'] = True # Reaffirm it's part of a continuation chain
            else:
                # This indented line is not a valid continuation line
                raise ParseError("Invalid continuation line", lineno)
            continue

