    lines = text.splitlines()
    current_section = None
    section_keys = {}

    for i, line in enumerate(lines):
        lineno = i + 1
        stripped_line = line.lstrip()

        # 1. Blank line or comment
        if not stripped_line or stripped_line.startswith((';', '#')):
            continue

        # 2. Section header: [name]
        if stripped_line.startswith('[') and stripped_line.endswith(']'):
            name_raw = stripped_line[1:-1].strip()
            if not name_raw:
                raise ParseError("Empty section name", lineno)
            if name_raw in config._sections:
                raise ParseError(f"Duplicate section header '{name_raw}'", lineno)

            if current_section is not None:
                # This implies a section header appeared before a key line could establish a context
                # but we only check for key lines before any section in the loop below.
                pass

            config._sections[name_raw] = {}
            config._section_keys[name_raw] = []
            config._section_order.append(name_raw)
            current_section = name_raw
            continue

        # 3. Key line or Continuation line
        if '=' in stripped_line:
            if current_section is None:
                raise ParseError("Key line before any section header", lineno)

            key_part, value_part = stripped_line.split('=', 1)
            key = key_part.strip()

            if not key:
                raise ParseError("Empty key", lineno)

            if key in config._sections[current_section]:
                raise ParseError(f"Duplicate key '{key}' in section '{current_section}'", lineno)

            # Initialize value for the key, handling continuation lines later
            config._sections[current_section][key] = value_part.strip()
            config._section_keys[current_section].append(key)

            # Store info to check for continuation lines
            section_keys[current_section] = section_keys.get(current_section, {})
            section_keys[current_section][key] = {'value': value_part.strip(), 'continuation': False}
            continue

        # 4. Indented line (Potential continuation)
        if line.startswith((' ', '\t')):
            if current_section is None:
                raise ParseError("Indented line before any section header", lineno)

            # Check if it follows a key/continuation line in the current section
            keys_in_section = list(section_keys.get(current_section, {}).keys())

            if not keys_in_section:
                 # Should not happen if logic is correct, but catches general indentation errors
                raise ParseError("Indented line without preceding key line", lineno)

            # Simple heuristic: check if the last key added in this section was the one we're extending
            # Since we don't store context like "which key this indented line belongs to", 
            # we must assume it extends the *last* defined key in this section if it's not blank/comment.
            # The requirement states: "comes directly after a key line or another continuation line"

            last_key = config._section_keys[current_section][-1]
            last_key_info = section_keys[current_section][last_key]

            if last_key_info['continuation']:
                # It's a continuation line for the last key, append it.
                new_value_part = line.strip()
                current_value = config._sections[current_section][last_key]
                config._sections[current_section][last_key] = f"{current_value}\n{new_value_part}"
                last_key_info['continuation'] = True # Reaffirm it's part of a continuation chain
            else:
                # This indented line is not a valid continuation line
                raise ParseError("Invalid continuation line", lineno)
            continue

        # 5. Any other line
        raise ParseError("Unrecognized line format", lineno)

    return config
