        node = self.root
        for char in word_folded:
            if char not in node:
                node[char] = {}
            node = node[char]

        # Store data at the end of the word
        if '_data' not in node:
            node['_data'] = {}
        node['_data']['original'] = original_word
        node['_data']['weight'] = weight
        node['_data']['is_end'] = True

    def add(self, word: str, weight: float = 1.0):
        if not word:
            raise ValueError("Word cannot be empty.")
        word_folded = word.casefold()
        node = self.root

        # Traverse to find or create the path
        for char in word_folded:
