                node['_data'] = {}
            node['_data']['original'] = word
            node['_data']['weight'] = weight
            node['_data']['is_end'] = True
            self.word_count += 1
        else:
            # Word exists, replace it
            node['_data']['original'] = word
            node['_data']['weight'] = weight

