            word_data = node['_data']
            # Reconstruct the original word from the path traversal if necessary, 
            # but since we store 'original' at the end node, we use that.
            original_word = word_data['original']
            weight = word_data['weight']

            if is_prefix_match:
                results.append({
                    'word': original_word,
                    'weight': weight,
                    'prefix_folded': current_prefix_folded
                })

        for char, next_node in node.items():
            if char not in ('_data'):
                self._find_all_matches(next_node, current_prefix_folded + char, prefix_folded, results)

    def complete(self, prefix: str, k: int = 10) -> list[str]:
        if k == 0:
            return []
        if k < 0:
            raise ValueError("k cannot be negative.")

        prefix_folded = prefix.casefold()
        results = []

        # 1. Traverse to the node corresponding to the end of the prefix
        node = self.root
        for char in prefix_folded:
            if char not in node:
                return [] # No words start with this prefix
            node = node[char]

        # 2. From this node, recursively find all descendant words
        # The current_prefix_folded passed to _find_all_matches should be the prefix_folded itself
        self._find_all_matches(node, prefix_folded, prefix_folded, results)

        # 3. Sort the results:
        #    Primary: weight (descending)
        #    Secondary: casefolded form (ascending alphabetically)
        results.sort(key=lambda x: (-x['weight'], x['prefix_folded']))

        # 4. Return up to k words, using the stored original spelling
        return [r['word'] for r in results[:k]]

