        mid = low + (high - low) // 2
        if a[mid] == x:
            result = mid
            low = mid + 1
        elif a[mid] < x:
            low = mid + 1
        else:
            high = mid - 1
    return result

def insertion_point(a: list[int], x: int) -> int:
    low = 0
    high = len(a)
    while low < high:
        mid = low + (high - low) // 2
        if a[mid] < x:
            low = mid + 1
        else:
            high = mid
    return low

def count(a: list[int], x: int) -> int:
    first = first_index(a, x)
    if first == -1:
        return 0
    last = last_index(a, x)
    return last - first + 1

def search_rotated(a: list[int], x: int) -> int:
    if not a:
        return -1
    low = 0
    high = len(a) - 1
    while low <= high:
        mid = low + (high - low) // 2
        if a[mid] == x:
            return mid

        # Check if the left half is sorted
        if a[low] <= a[mid]:
            # If x is within the sorted left half
            if a[low] <= x < a[mid]:
                high = mid - 1
            else:
                # x is in the rotated right half
                low = mid + 1
        # The right half must be sorted
        else:
            # If x is within the sorted right half
            if a[mid] < x <= a[high]:
                low = mid + 1
            else:
                # x is in the rotated left half
                high = mid - 1
    return -1

def rotation_offset(a: list[int]) -> int:
    if not a:
        raise ValueError("Input list cannot be empty")
    low = 0
    high = len(a) - 1
    if a[low] <= a[high]:
        return 0

    while low <= high:
        mid = low + (high - low) // 2
        mid_next = (mid + 1) % len(a)

        if a[mid] > a[mid_next]:
            return mid_next

        if a[low] <= a[mid] < a[high]: # Should not happen if not rotated, but for completeness
             return 0

        if a[low] <= a[mid]: # Left half is sorted, pivot is in right half
            low = mid + 1
        else: # Right half is sorted, pivot is in left half (including mid)
            high = mid - 1
    return 0 # Should be unreachable for non-empty, rotated array

def isqrt(n: int) -> int:
    if not isinstance(n, int):
        raise TypeError("Input must be an integer")
    if n < 0:
        raise ValueError("Input cannot be negative")
    if n == 0:
        return 0

    low = 1
    high = n # Upper bound for square root is n itself, but can be tightened to n//2 + 1 for n > 1
    if n > 1:
        high = n // 2 + 1

    result = 1
    while low <= high:
        mid = low + (high - low) // 2
        mid_sq = mid * mid
        if mid_sq == n:
            return mid
        elif mid_sq < n:
            result = mid
            low = mid + 1
        else:
            high = mid - 1
    return result
