from typing import Any, Dict, Set, List, Tuple
import re

class FormulaError(ValueError):
    pass

class ErrorValue(str):
    """Represents a formula calculation error."""
    pass

# Regex for number: digits [. digits]
NUMBER_RE = r"\d+(\.\d+)?"

# Regex for reference: letters digits (case-insensitive)
# Max 26 letters (A-Z), max 3 digits (1-999)
REF_RE = r"[a-zA-Z]+\d{1,3}"

# Grammar components (simplified for tokenization/parsing logic)
# expr   := term {(+ | -) term}
# term   := unary {(* | /) unary}
# unary  := (+ | -) unary | number | ref | ( expr )
# number := digits [. digits]
# ref    := letters digits

def tokenize(formula: str) -> List[str]:
    """Tokenizes the formula string."""
    # This tokenizer needs to be robust enough to handle whitespace between tokens.
    # We look for operators, parentheses, numbers, and references.
    token_specification = [
        ('NUMBER', NUMBER_RE),
        ('REF', REF_RE),
        ('OP_ADD', r'\+'),
        ('OP_SUB', r'\-'),
        ('OP_MUL', r'\*'),
        ('OP_DIV', r'/'),
        ('LPAREN', r'\('),
        ('RPAREN', r'\)'),
        ('SKIP', r'[ \t]+'), # Whitespace
        ('MISMATCH', r'.'),   # Any other character
    ]
    tok_regex = '|'.join('(?P<%s>%s)' % pair for pair in token_specification)
    tokens = []
    for mo in re.finditer(tok_regex, formula):
        kind = mo.lastgroup
        value = mo.group()
        if kind == 'NUMBER':
            tokens.append(value)
        elif kind == 'REF':
            tokens.append(value)
        elif kind in ['OP_ADD', 'OP_SUB', 'OP_MUL', 'OP_DIV', 'LPAREN', 'RPAREN']:
            tokens.append(value)
        elif kind == 'SKIP':
            continue
        elif kind == 'MISMATCH':
            raise FormulaError(f"Unexpected character: {value}")
    return tokens

def parse_formula(source: str) -> Any:
    """
    Parses the formula text after '=' into an Abstract Syntax Tree (AST).
    Raises FormulaError on syntax or validity issues.
    """
    if not source.strip():
        raise FormulaError("Formula cannot be empty.")

    tokens = tokenize(source)

    # Simple recursive descent parser structure:
    # Expression -> Term { ('+' | '-') Term }
    # Term -> Unary { ('*' | '/') Unary }
    # Unary -> ('+' | '-') Unary | Number | Ref | '(' Expression ')'

    class ASTNode:
        pass

    class NumberNode(ASTNode):
        def __init__(self, value: str):
            self.value = value

    class RefNode(ASTNode):
        def __init__(self, name: str):
            self.name = name.upper()

    class BinaryOpNode(ASTNode):
        def __init__(self, op: str, left: ASTNode, right: ASTNode):
            self.op = op
            self.left = left
            self.right = right

    class UnaryOpNode(ASTNode):
        def __init__(self, op: str, operand: ASTNode):
            self.op = op
            self.operand = operand

    class FormulaParser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0

        def peek(self):
            if self.pos < len(self.tokens):
                return self.tokens[self.pos]
            return None

        def consume(self, expected=None):
            if self.pos >= len(self.tokens):
                raise FormulaError("Incomplete expression.")
            token = self.tokens[self.pos]
            if expected and token != expected:
                raise FormulaError(f"Expected '{expected}' but got '{token}'.")
            self.pos += 1
            return token

        def parse_primary(self) -> ASTNode:
            token = self.peek()
            if token is None:
                raise FormulaError("Unexpected end of formula.")

            if token.isdigit() or (token.startswith('-') and token[1:].isdigit()): # Basic check for number start
                self.consume()
                # For simplicity in this scope, we rely on the number tokenization being correct.
                # If the token is a number string from tokenizer:
                if re.fullmatch(NUMBER_RE, token):
                    return NumberNode(token)

            elif re.fullmatch(REF_RE, token):
                self.consume()
                return RefNode(token)

            elif token == '(':
                self.consume('(')
                node = self.parse_expr()
                self.consume(')')
                return node

            elif token == '+' or token == '-':
                # Unary operator
                op = self.consume()
                operand = self.parse_primary() # Unary binds tighter than binary, so we recursively call primary parser for the operand
                if isinstance(operand, BinaryOpNode) and operand.op in ('+', '-', '*', '/'):
                    # If primary parser returned a binary op, this is likely wrong structure for unary.
                    # But given the grammar, Unary -> (+ | -) Unary | ...
                    # If it's a unary operator, it should be followed by a primary expression.
                    # We treat the unary operator as part of the unary node creation.
                    return UnaryOpNode(op, operand)
                return UnaryOpNode(op, operand)

            else:
                raise FormulaError(f"Unexpected token in primary expression: {token}")

        def parse_unary(self) -> ASTNode:
            token = self.peek()
            if token == '+' or token == '-':
                op = self.consume()
                operand = self.parse_unary() # Recursive call for unary chain
                return UnaryOpNode(op, operand)
            return self.parse_primary()

        def parse_term(self) -> ASTNode:
            node = self.parse_unary()

            while self.peek() in ('*', '/'):
                op = self.consume()
                right = self.parse_unary()
                node = BinaryOpNode(op, node, right)
            return node

        def parse_expr(self) -> ASTNode:
            node = self.parse_term()

            while self.peek() in ('+', '-'):
                op = self.consume()
                right = self.parse_term()
                node = BinaryOpNode(op, node, right)
            return node

    parser = FormulaParser(tokens)
    ast = parser.parse_expr()

    if parser.pos != len(tokens):
        raise FormulaError("Incomplete expression or unexpected tokens remaining.")

    # Basic validation: check reference validity (handled in references() later, but can check here)
    # Reference validation (max 26 letters, 1-999 row, no leading zeros in row)
    # We defer full validation to references() for better separation of concerns.

    return ast

def references(tree: Any) -> Set[str]:
    """Recursively extracts all unique, upper-case cell references from the AST."""

    ref_set: Set[str] = set()

    def traverse(node):
        if isinstance(node, RefNode):
            ref_set.add(node.name)
        elif isinstance(node, BinaryOpNode):
            traverse(node.left)
            traverse(node.right)
        elif isinstance(node, UnaryOpNode):
            traverse(node.operand)
        elif isinstance(node, NumberNode):
            pass # No references in numbers
        else:
            # Should not happen if AST is well-formed
            pass

    traverse(tree)
    return ref_set

def evaluate(tree: Any, lookup: callable) -> Any:
    """
    Computes the formula's value.
    lookup(name) must return: int, float, str, None, or ErrorValue.
    """

    def apply_op(op: str, left_val: Any, right_val: Any) -> Any:
        # Rule 3: If either operand is an error value, the result is that error value (left one if both).
        if isinstance(left_val, ErrorValue):
            return left_val
        if isinstance(right_val, ErrorValue):
            return right_val
        # Rule 3: If an operand is text, the result is #ERROR!
        if isinstance(left_val, str) and not isinstance(left_val, ErrorValue):
            return ErrorValue("#ERROR!")
        if isinstance(right_val, str) and not isinstance(right_val, ErrorValue):
            return ErrorValue("#ERROR!")

        # Now we know both are numbers (int/float) or None (treated as 0 later if it was a reference, 
        # but here we are evaluating the expression tree, so we assume operands are concrete values or errors)

        l_num = left_val if isinstance(left_val, (int, float)) else 0
        r_num = right_val if isinstance(right_val, (int, float)) else 0

        if op == '+':
            return l_num + r_num
        elif op == '-':
            return l_num - r_num
        elif op == '*':
            return l_num * r_num
        elif op == '/':
            if r_num == 0:
                return ErrorValue("#ERROR!")
            return l_num / r_num
        return ErrorValue("#ERROR!") # Should not happen

    def resolve_value(node: Any) -> Any:
        if isinstance(node, NumberNode):
            try:
                return int(node.value) if '.' not in node.value else float(node.value)
            except ValueError:
                return ErrorValue("#ERROR!")

        elif isinstance(node, RefNode):
            # Rule 2: A reference gives the cell's value.
            cell_value = lookup(node.name)
            if cell_value is None:
                return 0 # Empty cell gives 0
            if isinstance(cell_value, ErrorValue):
                return cell_value # Propagate error value
            if isinstance(cell_value, str) and not isinstance(cell_value, ErrorValue):
                # Rule 2 exception: If the formula is *only* a reference, return text unchanged.
                # We check if this node is the root or if it's part of a chain that resolves to text.
                # For simplicity matching Rule 2: if the value is text, return text.
                return cell_value
            return cell_value # Return int/float

        elif isinstance(node, BinaryOpNode):
            left_val = resolve_value(node.left)
            right_val = resolve_value(node.right)
            return apply_op(node.op, left_val, right_val)

        elif isinstance(node, UnaryOpNode):
            operand_val = resolve_value(node.operand)

            if isinstance(operand_val, ErrorValue):
                return operand_val

            # Unary sign handling
            if node.op == '+':
                return operand_val
            elif node.op == '-':
                if isinstance(operand_val, (int, float)):
                    return -operand_val
                # If it's text or an error, it becomes an error/text depending on context.
                # Since unary negation on text is not specified, we treat it as #ERROR! for non-numeric text.
                return ErrorValue("#ERROR!")

        return ErrorValue("#ERROR!") # Fallback

    return resolve_value(tree)
