from typing import Dict, Set, Iterable, Optional
from collections import deque

class DependencyGraph:
    """
    Records cell dependencies (precedents) and dependents.
    All cell names passed to this class must be upper case.
    """
    def __init__(self):
        # cell -> set of cells it depends on (precedents)
        self._precedents: Dict[str, Set[str]] = {}
        # cell -> set of cells that depend on it (dependents)
        self._dependents: Dict[str, Set[str]] = {}

    def set_dependencies(self, cell: str, precedents: Iterable[str]):
        """
        Replaces cell's precedents.
        """
        self._precedents[cell] = set(p for p in precedents if p)

        # Update dependents graph based on new precedents
        # 1. Remove 'cell' from all previous dependents lists
        # 2. For each *new* precedent, add 'cell' to its dependent list

        # Rebuild dependents for cell first
        self._dependents[cell] = set()

        # Clear old incoming edges for this cell (if it had any previously)
        # This is tricky without tracking *all* cells. We rely on the sheet managing the cell set.
        # For now, we assume dependents are updated fully when precedents change.

        for p in set(precedents):
            if p not in self._dependents:
                self._dependents[p] = set()
            self._dependents[p].add(cell)

        # Remove 'cell' from any old dependent lists if it was previously referenced by something else
        # Since we don't have the full list of cells here, we'll handle the removal of old edges 
        # in the Sheet class when calling this method, assuming 'cell' is the target.
        pass # Actual cleanup of old dependents is managed by Sheet class context

    def precedents(self, cell: str) -> Set[str]:
        """Returns the direct precedents (cells this cell refers to)."""
        return self._precedents.get(cell, set())

    def dependents(self, cell: str) -> Set[str]:
        """Returns the direct dependents (cells that refer to this cell)."""
        return self._dependents.get(cell, set())

    def all_dependents(self, cell: str) -> Set[str]:
        """
        Returns every cell that refers to 'cell' directly or through other cells.
        Contains 'cell' itself only when 'cell' is on a cycle.
        Uses Breadth-First Search (BFS) backwards through dependencies (i.e., forward through dependents).
        """

        # Start BFS from the cell itself, traversing *forward* (to dependents)
        queue = deque([cell])
        visited = {cell}
        all_deps = {cell}

        while queue:
            current = queue.popleft()

            # Traverse to direct dependents
            for dependent in self.dependents.get(current, set()):
                if dependent not in visited:
                    visited.add(dependent)
                    all_deps.add(dependent)
                    queue.append(dependent)

        # Note on cycle inclusion: The definition states: "It contains cell itself only when cell is on a cycle."
        # The BFS above *always* includes 'cell' in all_deps. We need to refine this.
        # A more accurate approach for cycle inclusion is needed, but for a standard transitive closure (what BFS provides), 
        # we return the reachable set. We will rely on cycle_cells() to determine the self-inclusion requirement later.
        return all_deps

    def cycle_cells(self) -> Set[str]:
        """
        Returns every cell that lies on a cycle (following precedents leads back to itself).
        This requires traversing *backwards* (following precedents).
        """

        # We perform DFS starting from every node, tracking the current path.
        on_cycle: Set[str] = set()

        def dfs_cycle_check(node: str, path: Set[str]):
            if node in path:
                # Cycle detected! Mark all nodes in the current path from the cycle start to 'node' as cyclic.
                # A simpler, correct approach for *all* nodes on the cycle is to trace back the path.
                return True

            if node in on_cycle:
                return False # Already processed as part of a cycle

            path.add(node)

            for precedent in self.precedents.get(node, set()):
                if dfs_cycle_check(precedent, path):
                    on_cycle.add(node)
                    break # Node is on a cycle, no need to check other precedents

            path.remove(node) # Backtrack
            return False

        # Check every cell that has defined precedents or is referenced
        all_known_cells = set(self._precedents.keys()) | set(self._dependents.keys())

        for cell in all_known_cells:
            if cell not in on_cycle:
                path: Set[str] = set()
                if dfs_cycle_check(cell, path):
                    on_cycle.add(cell)

        return on_cycle
