from typing import Dict, List, Any, Set
from .formula import FormulaError, ErrorValue, parse_formula, references, evaluate
from .graph import DependencyGraph

# Sheet dimensions
MAX_COL = 26 # A-Z
MAX_ROW = 999

class Sheet:
    def __init__(self):
        # Stores the raw input string for each cell: {name: raw_string}
        self._raw_values: Dict[str, str] = {}
        # Stores the calculated value: {name: value}
        self._computed_values: Dict[str, Any] = {}
        # Tracks formula evaluation counts
        self.evaluations: int = 0
        # Dependency tracking
        self.graph = DependencyGraph()

    def _name_to_coords(self, name: str) -> Tuple[int, int]:
        """Converts cell name (e.g., 'B7') to (col_idx, row_idx)."""
        name = name.upper()
        if not name:
            raise ValueError("Cell name cannot be empty.")

        col_str = "".join(filter(str.isalpha, name))
        row_str = "".join(filter(str.isdigit, name))

        if not col_str or not row_str:
            raise ValueError(f"Invalid cell name format: {name}")

        # Column validation (A-Z)
        if not (1 <= len(col_str) <= MAX_COL) or not all('A' <= char <= 'Z' for char in col_str):
            raise ValueError(f"Column name '{col_str}' is invalid.")

        # Row validation (1-999, no leading zeros unless it's '0', but rows start at 1)
        if not row_str.isdigit() or len(row_str) > 3 or int(row_str) == 0 or (len(row_str) > 1 and row_str[0] == '0'):
            raise ValueError(f"Row number '{row_str}' is out of bounds or invalid.")

        col_idx = 0
        for char in col_str:
            col_idx = col_idx * 26 + (ord(char) - ord('A') + 1)

        row_idx = int(row_str)

        # Convert 1-based to 0-based if necessary, but let's stick to 1-based internally for simplicity matching problem description
        return col_idx, row_idx

    def _coords_to_name(self, col_idx: int, row_idx: int) -> str:
        """Converts (col_idx, row_idx) back to cell name (e.g., 'A1')."""
        if not (1 <= col_idx <= MAX_COL):
            raise ValueError("Column index out of bounds.")
        if not (1 <= row_idx <= MAX_ROW):
            raise ValueError("Row index out of bounds.")

        # Column conversion (1-based to letter)
        col_letter = ''
        while col_idx > 0:
            col_idx -= 1
            col_letter = chr(ord('A') + col_idx) + col_letter

        return f"{col_letter}{row_idx}"

    def _get_all_cell_names(self) -> List[str]:
        """Returns all cell names in row-major order, including empty ones."""
        all_names = []
        # Iterate through rows (1 to 999) then columns (1 to 26)
        for r in range(1, MAX_ROW + 1):
            for c in range(1, MAX_COL + 1):
                all_names.append(self._coords_to_name(c, r))
        return all_names

    def _get_non_empty_cell_names(self) -> List[str]:
        """Returns cell names that have been set (i.e., are in _raw_values)."""
        return sorted(self._raw_values.keys(), key=lambda name: (self._name_to_coords(name)[1], self._name_to_coords(name)[0]))

    def _update_dependencies_and_trigger(self, name: str, old_precedents: Set[str], new_precedents: Set[str]) -> List[str]:
        """
        Updates the graph structure and returns the list of cells that need recalculation 
        (the cell itself + all its dependents).
        """

        # 1. Update graph structure
        self.graph.set_dependencies(name, new_precedents)

        # 2. Determine cells to update (self + all dependents)
        # This is the transitive closure of dependents, which is what we need to recalculate.
        cells_to_update = self.graph.all_dependents(name)

        # We must ensure the return list is in row-major order.
        sorted_updates = sorted(list(cells_to_update), key=lambda n: (self._name_to_coords(n)[1], self._name_to_coords(n)[0]))

        return sorted_updates


    def _recalculate_value(self, name: str) -> Any:
        """
        Calculates the value for a single cell 'name'. 
        This function assumes all its precedents are up-to-date and it's not on a cycle.
        """
        raw_input = self._raw_values[name]

        if raw_input == '':
            return None

        try:
            # Check for formula
            if raw_input.startswith('='):
                formula_source = raw_input[1:].strip()

                # 1. Parse
                tree = parse_formula(formula_source)

                # 2. Get references and update graph if necessary (though this should ideally happen before calling _recalculate_value)
                # We rely on set() from _update_dependencies_and_trigger to ensure the graph is correct *before* the trigger list is generated.
                # For safety during evaluation, we must check if this cell is on a cycle.
                if name in self.graph.cycle_cells():
                    return ErrorValue("#CYCLE!")

                # 3. Evaluate
                # The lookup function needs to know the *current* computed values of precedents.
                def lookup(ref_name: str) -> Any:
                    # We must ensure the lookup uses the *computed* value, not the raw value.
                    return self._computed_values.get(ref_name)

                new_value = evaluate(tree, lookup)

                # Handle special case: A formula that is *only* a reference returns text unchanged.
                # This is handled inside evaluate(), so new_value should be correct.
                return new_value

            # Check for number literal
            try:
                if '.' in raw_input:
                    return float(raw_input)
                else:
                    return int(raw_input)
            except ValueError:
                # Must be text
                pass
        except FormulaError as e:
            return ErrorValue("#ERROR!")
        except ValueError:
             # Catch errors from _name_to_coords or other unexpected structural errors
            return ErrorValue("#ERROR!")

        # Otherwise, it is text
        return raw_input

    def set(self, name: str, raw: str) -> List[str]:
        """
        Stores the cell's input and triggers recalculation for affected cells.
        Returns the cells whose value may have changed, in row-major order.
        """
        name = name.upper()
        if name not in self._raw_values and not any(n.upper() == name for n in self._raw_values):
             try:
                 self._name_to_coords(name) # Validate name exists in sheet bounds
             except ValueError:
                 raise ValueError(f"Cell name '{name}' is outside the sheet bounds.")

        if not isinstance(raw, str):
            raise TypeError("Raw input must be a string.")

        old_raw = self._raw_values.get(name, '')
        self._raw_values[name] = raw

        # --- Dependency and Recalculation Trigger ---

        old_precedents = self.graph.precedents(name)
        new_precedents = set()

        if raw.startswith('='):
            try:
                formula_source = raw[1:].strip()
                tree = parse_formula(formula_source)
                new_precedents = references(tree)
            except FormulaError:
                # Formula parsing failed, sheet is unchanged, return empty list
                return []

        # If the content changed, or if dependencies changed, we need to recalculate
        if raw != old_raw or old_precedents != new_precedents:

            # 1. Update graph structure and get the list of cells that need updating
            # Note: This function updates the internal graph state.
            cells_to_recalc = self._update_dependencies_and_trigger(name, old_precedents, new_precedents)

            # 2. Recalculate values iteratively in row-major order
            recalculated_cells: List[str] = []

            # We must recalculate *all* cells in cells_to_recalc, in order,
            # respecting cycle rules and ensuring dependencies are met.

            # For cycle detection during evaluation:
            cycle_cells = self.graph.cycle_cells()

            for cell_name in cells_to_recalc:
                # Check if the cell is on a cycle first (Rule 2)
                if cell_name in cycle_cells:
                    new_val = ErrorValue("#CYCLE!")
                else:
                    # Calculate value (Rule 1 & 3)
                    new_val = self._recalculate_value(cell_name)

                old_value = self._computed_values.get(cell_name)

                # Only update and count if the value has genuinely changed
                # We compare types first if one is error, otherwise standard comparison.
                value_changed = False
                if old_value is None and new_val is not None:
                    value_changed = True
                elif new_val is None and old_value is not None:
                    value_changed = True
                elif new_val != old_value:
                    value_changed = True

                if value_changed:
                    self._computed_values[cell_name] = new_val
                    recalculated_cells.append(cell_name)

                    # Rule 3: Increment evaluation count only if it was a formula that successfully evaluated
                    if new_val != None and not isinstance(new_val, ErrorValue) and cell_name in self._raw_values and self._raw_values[cell_name].startswith('='):
                        self.evaluations += 1

            # Return cells whose value *changed*
            return recalculated_cells

        return []

    def get(self, name: str) -> Any:
        """Returns the cell's calculated value."""
        name = name.upper()
        if name not in self._raw_values:
             try:
                 self._name_to_coords(name)
                 # If valid name but not set, it's an empty cell, which returns None
                 return None 
             except ValueError:
                 raise ValueError(f"Cell name '{name}' is outside the sheet bounds.")

        return self._computed_values.get(name)

    def raw(self, name: str) -> str:
        """Returns the input last stored."""
        name = name.upper()
        if name not in self._raw_values:
             try:
                 self._name_to_coords(name)
                 return ''
             except ValueError:
                 raise ValueError(f"Cell name '{name}' is outside the sheet bounds.")
        return self._raw_values[name]

    def cells(self) -> List[str]:
        """Returns the non-empty cells in row-major order."""
        return sorted(self._raw_values.keys(), key=lambda name: (self._name_to_coords(name)[1], self._name_to_coords(name)[0]))

    # For internal use during testing/debugging, not required by prompt interface
    # def _get_all_cells_in_order(self) -> List[str]:
