from typing import Dict, List, Optional
from .versions import Version, Range

class PackageIndex:
    def __init__(self):
        # Structure: {name: {version_str: {'requires': {dep_name: spec_str}, 'version_obj': Version}}}
        self.packages: Dict[str, Dict[str, dict]] = {}

    def add(self, name: str, version_str: str, requires: Optional[Dict[str, str]] = None):
        if name in self.packages and version_str in self.packages[name]:
            raise ValueError(f"Package {name} version {version_str} already exists.")

        try:
            version_obj = Version(version_str)
        except ValueError:
            raise ValueError(f"Bad version string provided: {version_str}")

        if name not in self.packages:
            self.packages[name] = {}

        self.packages[name][version_str] = {
            'requires': requires if requires is not None else {},
            'version_obj': version_obj
        }

    def versions(self, name: str) -> List[Version]:
        if name not in self.packages:
            return []

        versions = []
        for v_data in self.packages[name].values():
            versions.append(v_data['version_obj'])

        # Newest first
        return sorted(versions, reverse=True)

    def requirements(self, name: str, version: Version) -> Dict[str, Range]:
        if name not in self.packages:
            raise KeyError(f"Package {name} not found in index.")

        if version_str := str(version) not in self.packages[name]:
            raise KeyError(f"Version {version_str} of package {name} not found in index.")

        data = self.packages[name][version_str]

        ranges: Dict[str, Range] = {}
        for dep_name, spec_str in data['requires'].items():
            ranges[dep_name] = Range(spec_str)
        return ranges

    @classmethod
    def from_dict(cls, data: dict) -> 'PackageIndex':
        index = cls()
        for name, versions_data in data.items():
            index.packages[name] = {}
            for version_str, dep_info in versions_data.items():
                requires = dep_info.get('dep', {})
                index.add(name, version_str, requires=requires)
        return index
