from typing import Dict, List, Optional, Tuple
from .versions import Version, Range
from .index import PackageIndex

class ResolutionError(Exception):
    def __init__(self, package: str, explanation: str):
        self.package = package
        self.explanation = explanation
        super().__init__(str(self))

def resolve(index: PackageIndex, requirements: Dict[str, str]) -> Dict[str, Version]:

    # 1. Initialize state
    # Order: list of package names, initially root requirements sorted alphabetically.
    order: List[str] = sorted(requirements.keys())

    # Selected: dict mapping package name to its selected Version object
    selected: Dict[str, Version] = {}

    # State for DFS

    def dfs(current_order: List[str], current_selected: Dict[str, Version]) -> Optional[Dict[str, Version]]:

        # Find the next package to resolve
        next_package = None
        for pkg_name in current_order:
            if pkg_name not in current_selected:
                next_package = pkg_name
                break

        # Success case: all packages in order are selected
        if next_package is None:
            return current_selected

        pkg_name = next_package

        # 2. Gather constraints for pkg_name
        constraints: List[Tuple[str, Range]] = [] # (requirer, Range)

        # Root requirement constraint
        root_spec_str = requirements.get(pkg_name)
        if root_spec_str:
            try:
                root_range = Range(root_spec_str)
                constraints.append(('<root>', root_range))
            except ValueError as e:
                # This should ideally be caught before calling resolve, but for robustness:
                raise ResolutionError(pkg_name, f"Initial root requirement error: {e}")

        # Constraints from already selected packages
        for selected_pkg_name, selected_version in current_selected.items():
            try:
                ranges = index.requirements(selected_pkg_name, selected_version)
                if pkg_name in ranges:
                    range_obj = ranges[pkg_name]
                    # Requirer format: "name version"
                    requirer_str = f"{selected_pkg_name} {selected_version}"
                    constraints.append((requirer_str, range_obj))
            except KeyError:
                # This implies an internal inconsistency if a selected package requires something unknown
                pass 

        # 3. Identify candidates (versions of pkg_name)
        candidates = index.versions(pkg_name)

        if not candidates:
            # No versions known, fail immediately.
            explanation = [
                f"cannot resolve {pkg_name}",
                "  no versions of {pkg_name} are known"
            ]
            raise ResolutionError(pkg_name, "\n".join(explanation))

        acceptable_candidates: List[Tuple[Version, List[str]]] = []

        for candidate_v in candidates:

            # Check if candidate satisfies all explicit constraints
            is_acceptable = True
            for requirer, required_range in constraints:
                if not required_range.contains(candidate_v):
                    is_acceptable = False
                    break

            if not is_acceptable:
                # Record exclusion reason for later error report if this candidate was the only one or if we need to report it
                # For now, we just skip it and check the next one.
                continue

            # Check dependency constraints (backward check)
            candidate_ranges = index.requirements(pkg_name, candidate_v)

            is_dependency_ok = True
            for dep_name, dep_range in candidate_ranges.items():
                if dep_name in current_selected:
                    selected_dep_version = current_selected[dep_name]
                    if not dep_range.contains(selected_dep_version):
                        is_dependency_ok = False
                        break

            if is_dependency_ok:
                # Candidate is acceptable! Gather newly required dependencies.
                new_deps = []
                for dep_name, _ in candidate_ranges.items():
                    if dep_name not in current_selected and dep_name not in current_order:
                        new_deps.append(dep_name)

                acceptable_candidates.append((candidate_v, sorted(new_deps)))

        # 4. Try each acceptable candidate recursively (Backtracking)
        for candidate_v, new_deps in acceptable_candidates:

            # Prepare for recursive call
            next_order = current_order + sorted(new_deps)
            next_selected = current_selected.copy()
            next_selected[pkg_name] = candidate_v

            # Recurse
            result = dfs(next_order, next_selected)

            if result is not None:
                # Success path found
                return result

        # 5. Failure case: No candidate led to success

        # Construct error explanation
        explanation_lines = [f"cannot resolve {pkg_name}"]

        # Add constraint checks
        for requirer, required_range in constraints:
            explanation_lines.append(f"  {requirer} requires {pkg_name} {required_range}")

        # Add version exclusion checks for *all* candidates (as per example structure)
        # We check all candidates, not just the ones that failed the first check, to generate the required report format.

        if not candidates:
             # Handled above, but for completeness of this block
             pass 
        else:
            # Collect all candidates (sorted newest first)
            all_candidates = index.versions(pkg_name)

            for candidate_v in all_candidates:
                # Check if it failed due to constraint violation
                constraint_violated = False
                for requirer, required_range in constraints:
                    if not required_range.contains(candidate_v):
                        explanation_lines.append(f"  {pkg_name} {candidate_v} is excluded by the constraints")
                        constraint_violated = True
                        break

                if not constraint_violated:
                    # Check dependency violation
                    candidate_ranges = index.requirements(pkg_name, candidate_v)
                    dependency_conflict = False
                    for dep_name, dep_range in candidate_ranges.items():
                        if dep_name in current_selected:
                            selected_dep_version = current_selected[dep_name]
                            if not dep_range.contains(selected_dep_version):
                                explanation_lines.append(f"  {pkg_name} {candidate_v} requires {dep_name} {dep_range}, but {dep_name} {selected_dep_version} is selected")
                                dependency_conflict = True
                                break
                    if dependency_conflict:
                        pass # Already reported
                    elif not constraint_violated:
                        # If it passed all constraints but still didn't lead to a successful path, 
                        # it means a subsequent dependency failed. This case is implicitly covered by 
                        # the failure to return from the recursive DFS call for this candidate.
                        # The example suggests only reporting *exclusion* reasons in this final block.
                        # We only report explicit constraint/dependency violations here.
                        pass

        explanation = "\n".join(explanation_lines)
        raise ResolutionError(pkg_name, explanation)

    # Start DFS
    return dfs(order, selected)
