from functools import total_ordering

@total_ordering
class Version:
    def __init__(self, text: str):
        try:
            parts = list(map(int, text.split('.')))
            if len(parts) != 3:
                raise ValueError
            if any(p < 0 for p in parts):
                raise ValueError
            if any(len(str(p)) > 1 and p == 0 for p in parts):
                raise ValueError
            self.major, self.minor, self.patch = parts
        except ValueError:
            raise ValueError(f"Invalid version string: {text}")

    def __lt__(self, other):
        return (self.major, self.minor, self.patch) < (other.major, other.minor, other.patch)

    def __le__(self, other):
        return (self.major, self.minor, self.patch) <= (other.major, other.minor, other.patch)

    def __gt__(self, other):
        return (self.major, self.minor, self.patch) > (other.major, other.minor, other.patch)

    def __ge__(self, other):
        return (self.major, self.minor, self.patch) >= (other.major, other.minor, other.patch)

    def __eq__(self, other):
        return (self.major, self.minor, self.patch) == (other.major, other.minor, other.patch)

    def __hash__(self):
        return hash((self.major, self.minor, self.patch))

    def __str__(self):
        return f"{self.major}.{self.minor}.{self.patch}"

class Range:
    def __init__(self, spec: str):
        self.constraints = []
        self._parse_spec(spec)

    def _parse_spec(self, spec: str):
        spec = spec.strip()
        if not spec:
            self.constraints = []
            return

        parts = [p.strip() for p in spec.split(',')]
        for part in parts:
            if not part:
                continue

            if part == '*':
                self.constraints.append(('ANY', None))
                continue

            # Check for operators
            if part.startswith('=='):
                op = '=='
                version_str = part[2:].strip()
                self._add_constraint(op, version_str)
            elif part.startswith('!='):
                op = '!='
                version_str = part[2:].strip()
                self._add_constraint(op, version_str)
            elif part.startswith('>='):
                op = '>='
                version_str = part[2:].strip()
                self._add_constraint(op, version_str)
            elif part.startswith('^'):
                op = '^'
                version_str = part[1:].strip()
                self._add_caret_constraint(version_str)
            elif part.startswith('~'):
                op = '~'
                version_str = part[1:].strip()
                self._add_tilde_constraint(version_str)
            elif part.startswith('>'):
                op = '>'
                version_str = part[1:].strip()
                self._add_constraint(op, version_str)
            elif part.startswith('<'):
                op = '<'
                version_str = part[1:].strip()
                self._add_constraint(op, version_str)
            elif part.startswith('<='):
                op = '<='
                version_str = part[2:].strip()
                self._add_constraint(op, version_str)
            else:
                try:
                    Version(part)
                    self._add_constraint('==', part)
                except ValueError:
                    raise ValueError(f"Unknown operator or bad constraint in spec: {part}")

    def _add_constraint(self, op: str, version_str: str):
        try:
            version = Version(version_str)
        except ValueError as e:
            raise ValueError(f"Bad version in constraint: {version_str}. {e}")
        self.constraints.append((op, version))

    def _add_caret_constraint(self, version_str: str):
        try:
            v = Version(version_str)
        except ValueError as e:
            raise ValueError(f"Bad version in caret constraint: {version_str}. {e}")

        major, minor, patch = v.major, v.minor, v.patch

        if major == 0 and minor == 0 and patch == 0:
            lower_bound = v
            upper_bound = Version("0.0.1")
        elif major == 0:
            lower_bound = v
            upper_bound = Version(f"0.{minor + 1}.0")
        else:
            lower_bound = v
            upper_bound = Version(f"{major + 1}.0.0")

        self.constraints.append(('>=', lower_bound))
        self.constraints.append(('<', upper_bound))

    def _add_tilde_constraint(self, version_str: str):
        try:
            v = Version(version_str)
        except ValueError as e:
            raise ValueError(f"Bad version in tilde constraint: {version_str}. {e}")

        major, minor, patch = v.major, v.minor, v.patch

        lower_bound = v
        if major == 0 and minor == 0 and patch == 0:
            upper_bound = Version("0.0.1")
        elif major == 0 and minor == 0:
            upper_bound = Version(f"0.0.{patch + 1}")
        elif major == 0:
            upper_bound = Version(f"0.{minor + 1}.0")
        else:
            upper_bound = Version(f"{major}.{minor + 1}.0")

        self.constraints.append(('>=', lower_bound))
        self.constraints.append(('<', upper_bound))

    def contains(self, v: Version) -> bool:
        for op, required_v in self.constraints:
            if op == 'ANY':
                continue

            if op == '==':
                if v != required_v:
                    return False
            elif op == '!=':
                if v == required_v:
                    return False
            elif op == '>=':
                if v < required_v:
                    return False
            elif op == '<':
                if v >= required_v:
                    return False
            elif op == '>':
                if v <= required_v:
                    return False
            elif op == '<=':
                if v > required_v:
                    return False
        return True

    def __contains__(self, v: Version) -> bool:
        return self.contains(v)

    def __str__(self):
        return ",".join([f"{op}{v}" if op != 'ANY' else '*' for op, v in self.constraints if op != 'ANY'])
